/**
 * @name Tainted data to code execution in Jinja2
 * @description Checking if untrusted data can reach code execution functions in Jinja2
 * @kind path-problem
 * @problem.severity error
 * @id py/tainted-code-execution
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module TaintedCodeExecConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for exec/eval calls
    sink instanceof CodeExecution or
    exists(DataFlow::CallCfgNode call |
      call = API::builtin(["exec", "eval", "compile"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module TaintedCodeExecFlow = TaintTracking::Global<TaintedCodeExecConfig>;
import TaintedCodeExecFlow::PathGraph

from TaintedCodeExecFlow::PathNode source, TaintedCodeExecFlow::PathNode sink
where TaintedCodeExecFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Tainted data reaches code execution from $@.", source.getNode(), "user input"

/**
 * @name Server-side Template Injection (SSTI) in Jinja2
 * @description Checking for potential template injection vulnerabilities where untrusted data reaches template rendering
 * @kind path-problem
 * @problem.severity error
 * @id py/template-injection
 * @tags security
 *        external/cwe/cwe-1336
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module TemplateInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for calls to jinja2 rendering methods
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("jinja2").getMember("Environment").getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("jinja2").getMember("Template").getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("jinja2.environment").getMember("Environment").getACall() and
      sink = call.getArg(0)
    )
  }
}

module TemplateInjectionFlow = TaintTracking::Global<TemplateInjectionConfig>;
import TemplateInjectionFlow::PathGraph

from TemplateInjectionFlow::PathNode source, TemplateInjectionFlow::PathNode sink
where TemplateInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Template injection from $@.", source.getNode(), "user input"

/**
 * @name Code injection via eval/exec in Jinja2
 * @description Untrusted data reaching eval/exec calls in Jinja2
 * @kind path-problem
 * @problem.severity error
 * @id py/code-injection-jinja2
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module Jinja2CodeInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for eval/exec calls in Jinja2
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("eval").getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("exec").getACall() and
      sink = call.getArg(0)
    )
  }
}

module Jinja2CodeInjectionFlow = TaintTracking::Global<Jinja2CodeInjectionConfig>;
import Jinja2CodeInjectionFlow::PathGraph

from Jinja2CodeInjectionFlow::PathNode source, Jinja2CodeInjectionFlow::PathNode sink
where Jinja2CodeInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Code injection from $@.", source.getNode(), "user input"
